'use strict';

// MODULES //

var getSource = require( '@data-apis/registry/get-source' );
var sourceFingerprint = require( '@data-apis/registry/source-fingerprint' );


// MAIN //

/**
* Asserts that registered endpoints have not reused existing source IDs.
*
* @param {Object} registry - registry
* @param {Object} index - data index
* @throws {Error} if source history is inconsistent
*/
function assertRegistryHistory( registry, index ) {
	index.records.forEach( function validateRow( row ) {
		var source = getSource( registry, row.library_id, row.source_id ).source;
		var fingerprint;

		if ( !source ) {
			return;
		}
		fingerprint = sourceFingerprint( source );
		if ( fingerprint !== row.source_fingerprint ) {
			throw new Error( 'Registered endpoint changed without a new source ID: ' + row.library_id + '/' + row.source_id );
		}
		if ( source.type !== row.origin.type ) {
			throw new Error( 'Registered source type differs from history: ' + row.library_id + '/' + row.source_id );
		}
		if ( source.type === 'ci_artifact' ) {
			if ( source.provider !== row.origin.provider || source.project.toLowerCase() !== row.origin.project.locator.toLowerCase() ) {
				throw new Error( 'Registered CI source differs from history: ' + row.library_id + '/' + row.source_id );
			}
		} else if ( source.url !== row.origin.endpoint ) {
			throw new Error( 'Registered URL source differs from history: ' + row.library_id + '/' + row.source_id );
		}
	} );
}


// EXPORTS //

module.exports = assertRegistryHistory;
